arrows.css:
.hephaistos.sr7-arrows {
	cursor:pointer;
	background:##back-color##;
	width:##back-size##px;
	height:##back-size##px;
	position:absolute;
	display:block;
	z-index:1000;
    border-radius:50%;
}
.hephaistos.sr7-arrows.sr7-touchhover {
	background:##back-hover##;
}
.hephaistos.sr7-arrows:before {
	font-family: 'revicons';
	font-size:18px;
	color:##arrow-color##;
	display:block;
	line-height: ##back-size##px;
	text-align: center;
}
.hephaistos.sr7-arrows.sr7-leftarrow:before {
	content: '##left-arrow##';
    margin-left:-2px;

}
.hephaistos.sr7-arrows.sr7-rightarrow:before {
	content: '##right-arrow##';
    margin-right:-2px;
}

bullets.css:
.hermes.sr7-bullets {
}

.hermes .sr7-bullet {
    overflow:hidden;
    border-radius:50%;
    width:##bullet-size##px;
    height:##bullet-size##px;
    background-color: rgba(0, 0, 0, 0);
    box-shadow: inset 0 0 0 ##border##px ##bullet-color##;
    -webkit-transition: background 0.3s ease;
    transition: background 0.3s ease;
    position:absolute;
}

.hermes .sr7-bullet.sr7-touchhover {
	  background-color: ##bullet-hover##;
}
.hermes .sr7-bullet:after {
  content: ' ';
  position: absolute;
  bottom: 0;
  height: 0;
  left: 0;
  width: 100%;
  background-color: ##bullet-color##;
  box-shadow: 0 0 1px ##bullet-color##;
  -webkit-transition: height 0.3s ease;
  transition: height 0.3s ease;
}
.hermes .sr7-bullet.selected:after {
  height:100%;
}

thumbs.css:
.hesperiden .sr7-thumb {
  opacity:1;
  -webkit-perspective: 600px;
  perspective: 600px;
}
.hesperiden .sr7-thumb .sr7-thumb-title {
    font-size:##title-font-size##px;
    position:absolute;
    margin-top:-10px;
    color:##title-color##;
    display:block;
    z-index:1000;
    background-color:##title-bg##;
    padding:5px 10px; 
    bottom:0px;
    left:0px;
    width:100%;
  box-sizing:border-box;
    text-align:center;
    overflow:hidden;
    white-space:nowrap;
    transition:all 0.3s;
    -webkit-transition:all 0.3s;
    transform:rotatex(90deg) translatez(0.001px);
    transform-origin:50% 100%;
    -webkit-transform:rotatex(90deg) translatez(0.001px);
    -webkit-transform-origin:50% 100%;
    opacity:0;
 }
.hesperiden .sr7-thumb.sr7-touchhover .sr7-thumb-title {
  	 transform:rotatex(0deg);
    -webkit-transform:rotatex(0deg);
    opacity:1;
}

